package com.example;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class ReportService {
    public String load(Path path) {
        try {
            return Files.readString(path);
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }
    }
}

